{"file_text": "@page "/chat"
@using sv_21c2f4f0481f4ba197f64ce792726d26.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelList Channels="channels"
                 SelectedChannelId="selectedChannel?.Id ?? 0"
                 OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@(selectedChannel?.Name ?? "")"
                 ChannelDescription="@(selectedChannel?.Description ?? "")"
                 Messages="messages"
                 ThreadReplyCounts="threadReplyCounts"
                 IsLoadingMore="isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadMoreMessages"
                 class="@(activeThread is null ? "full-width" : "")" />

    @if (activeThread is not null)
    {
        <ThreadPanel RootMessage="activeThread"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, int> threadReplyCounts = new();
    private bool isLoadingMore;

    private Message? activeThread;
    private List<Message> threadReplies = [];

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        activeThread = null;
        threadReplies = [];
        await ChatService.MarkChannelReadAsync(channel.Id);
        await BuildThreadReplyCounts();
    }

    private async Task LoadMoreMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            await BuildThreadReplyCounts();
        }

        isLoadingMore = false;
    }

    private async Task BuildThreadReplyCounts()
    {
        threadReplyCounts.Clear();
        // Identify thread starters: messages that have replies pointing to them
        var rootIds = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        foreach (var rootId in rootIds)
        {
            var thread = await ChatService.GetThreadAsync(rootId);
            if (thread.Count > 0)
            {
                threadReplyCounts[rootId] = thread.Count;
            }
        }
    }

    private async Task OpenThread(Message message)
    {
        // If the message is a reply, open its root thread; otherwise it is the root
        var rootMessage = message.ReplyToId is null
            ? message
            : messages.FirstOrDefault(m => m.Id == message.ReplyToId) ?? message;

        activeThread = rootMessage;
        threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
    }

    private async Task CloseThread()
    {
        activeThread = null;
        threadReplies = [];
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var sent = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(sent);
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannel is null || activeThread is null) return;
        var sent = await ChatService.SendMessageAsync(selectedChannel.Id, content, activeThread.Id);
        threadReplies.Add(sent);

        // Update reply count
        threadReplyCounts[activeThread.Id] = threadReplies.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        // Optimistically update the local message
        var msg = messages.FirstOrDefault(m => m.Id == reaction.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(reaction.Emoji, ["You"]));
            }
        }
    }
}
