@using sv_21c2f4f0481f4ba197f64ce792726d26.Services
@implements IAsyncDisposable
@inject IJSRuntime JS

<section class="message-area">
    <header class="message-area-header">
        <h2># @ChannelName</h2>
        <p>@ChannelDescription</p>
    </header>

    <div class="message-list" @ref="messageListRef">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }

        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ReplyCount="GetReplyCount(message.Id)"
                         OnOpenThread="() => OnOpenThread.InvokeAsync(message)"
                         OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
        }
    </div>

    <div class="message-input-area">
        <textarea class="message-input" @bind="newMessageText" @bind:event="oninput"
                  placeholder="Type a message…" @onkeydown="HandleKeyDown"></textarea>
        <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessageText)">Send</button>
    </div>
</section>

@code {
    [Parameter] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<Message> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private string newMessageText = "";
    private ElementReference messageListRef;
    private IJSObjectReference? module;
    private DotNetObjectReference<MessageArea>? dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/Pages/Chat/MessageArea.razor.js");
            dotNetRef = DotNetObjectReference.Create(this);
            await module.InvokeVoidAsync("registerScrollHandler", messageListRef, dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        await OnLoadMore.InvokeAsync();
    }

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessage();
        }
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessageText)) return;
        var text = newMessageText;
        newMessageText = "";
        await OnSendMessage.InvokeAsync(text);
    }

    public async ValueTask DisposeAsync()
    {
        dotNetRef?.Dispose();
        if (module is not null)
        {
            await module.DisposeAsync();
        }
    }
